def text_width_in(text: str, font_pt: float, face: str = "body", letter_spacing_pt: float = 0.0) -> float:
    """Width of `text` on one line, in inches."""
    m = METRICS.get(face, METRICS["body"])
    em = sum(m["widths"].get(ch, m["default"]) for ch in text)
    return (em * font_pt + letter_spacing_pt * len(text)) / 72.0
